import math

def sigma(n):
    # Calculate the sum of divisors of n
    s = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            s += i
            j = n // i
            if i != j:
                s += j
    return s

def tau(n):
    # Calculate the number of divisors of n
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            count += 1
            j = n // i
            if i != j:
                count += 1
    return count

candidates = {}
