import math

def sigma(n):
    if n == 1:
        return 1

    # Prime factorization
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Calculate sum of divisors
    sum_d = 1
    for p, k in factors.items():
        sum_d *= (p**(k+1) - 1) // (p - 1)
    return sum_d

def tau(n):
    if n == 1:
        return 1

    # Prime factorization
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Calculate number of divisors
    count = 1
    for k in factors.values():
        count *= (k + 1)
    return count

def is_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    root = int(math.isqrt(n))
    return root * root == n

