from itertools import permutations

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(n**0.5)
    return sqrt_n * sqrt_n == n

def solve_m81():
    divisors = [1, 3, 9, 27, 81]
    n = len(divisors)

    # Check necessary condition first
    sigma_m = sum(divisors)
    if not is_perfect_square(sigma_m):
        print(f"Sigma(81) = {sigma_m}. Not a perfect square. No solution possible.")
        return None

    print(f"Sigma(81) = {sigma_m} = {int(sigma_m**0.5)}^2. Searching for permutation...")

    for p in permutations(divisors):
        current_sum = 0
        is_valid = True

        # Check partial sums S_1 through S_{n-1}
        for i in range(n - 1):
            current_sum += p[i]
            if not is_perfect_square(current_sum):
                is_valid = False
                break

        # Check the final sum S_n (which is always sigma_m, already checked)
        if is_valid:
            current_sum += p[n-1]
            if is_perfect_square(current_sum):
                return list(p)

    return None

result = solve_m81()

if result:
    print(f"A valid permutation was found: {result}")
else:
